/*
 * Original-from-scratch behavioral reimplementation for the benchmark.
 * It mimics the observed Dropbear server command line and a small portion
 * of its TCP handshake/logging surface. It is not a real SSH server.
 */
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <fcntl.h>
#include <grp.h>
#include <netdb.h>
#include <signal.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
