#include <sys/socket.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <time.h>
#include <unistd.h>

#ifndef SO_BINDTODEVICE
#define SO_BINDTODEVICE 25
#endif

#define VERSION "2025.89"
#define DEFAULT_RECV_WINDOW 24576U
#define MAX_RECV_WINDOW 10485760U
#define MAX_PORTS 10
#define MAX_KEYS 64
#define MAX_CHILDREN 256
#define KEY_STRING_MAX 25000U

static const char *default_keys[] = {
    "/etc/dropbear/dropbear_rsa_host_key",
    "/etc/dropbear/dropbear_ecdsa_host_key",
    "/etc/dropbear/dropbear_ed25519_host_key",
};

struct listen_spec {
    char *orig;
    char *host;
    char *port;
};

struct options {
    int create_keys;
    int foreground;
    int inetd_mode;
    int pass_env;
    int no_motd;
    int disallow_root;
    int disable_password;
    int disable_root_password;
    int allow_blank;
    int twofactor;
    int no_local_forward;
    int no_remote_forward;
    int allow_forward_any;
    int disable_qos;
    char *bannerfile;
    char *authdir;
    char *group;
    char *forced_command;
    char *pidfile;
    char *interface;
    char *keyfiles[MAX_KEYS];
    int n_keyfiles;
    struct listen_spec ports[MAX_PORTS];
    int n_ports;
    /* Numeric argument strings are validated after banner/group processing. */
    char *maxauth_s;
    char *keepalive_s;
    char *idle_s;
    char *recvwin_s;
    unsigned recvwin_value;
    int have_valid_key;
};

static struct options g_opts;
static int g_listeners[MAX_PORTS * 4];
static int g_listener_count = 0;
static pid_t g_children[MAX_CHILDREN];
static int g_child_count = 0;
static volatile sig_atomic_t g_terminate = 0;
static char *g_written_pidfile = NULL;
static int g_is_parent = 1;
static char g_peer_desc[NI_MAXHOST + NI_MAXSERV + 8];
static volatile sig_atomic_t g_child_got_term = 0;

static void logmsg(const char *fmt, ...) __attribute__((format(printf,1,2)));
static void early_exit(const char *fmt, ...) __attribute__((format(printf,1,2), noreturn));

static void timestamp_prefix(FILE *f) {
    time_t now = time(NULL);
    struct tm tmv;
    localtime_r(&now, &tmv);
    char mon[8];
    strftime(mon, sizeof(mon), "%b", &tmv);
    fprintf(f, "[%ld] %s %02d %02d:%02d:%02d ",
            (long)getpid(), mon, tmv.tm_mday, tmv.tm_hour, tmv.tm_min, tmv.tm_sec);
}

static void logmsg(const char *fmt, ...) {
    va_list ap;
    timestamp_prefix(stderr);
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    fputc('\n', stderr);
    fflush(stderr);
}

static void early_exit(const char *fmt, ...) {
    va_list ap;
    timestamp_prefix(stderr);
    fputs("Early exit: ", stderr);
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    fputc('\n', stderr);
    fflush(stderr);
    if (g_written_pidfile) {
        unlink(g_written_pidfile);
    }
    exit(1);
}

static void early_exit_status0(const char *fmt, ...) __attribute__((format(printf,1,2), noreturn));
static void early_exit_status0(const char *fmt, ...) {
    va_list ap;
    timestamp_prefix(stderr);
    fputs("Early exit: ", stderr);
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    fputc('\n', stderr);
    fflush(stderr);
    if (g_written_pidfile) {
        unlink(g_written_pidfile);
    }
    exit(0);
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Dropbear server v" VERSION " https://matt.ucc.asn.au/dropbear/dropbear.html\n"
        "Usage: %s [options]\n"
        "-b bannerfile\tDisplay the contents of bannerfile before user login\n"
        "\t\t(default: none)\n"
        "-r keyfile      Specify hostkeys (repeatable)\n"
        "\t\tdefaults: \n"
        "\t\t- rsa /etc/dropbear/dropbear_rsa_host_key\n"
        "\t\t- ecdsa /etc/dropbear/dropbear_ecdsa_host_key\n"
        "\t\t- ed25519 /etc/dropbear/dropbear_ed25519_host_key\n"
        "-D\t\tDirectory containing authorized_keys file\n"
        "-R\t\tCreate hostkeys as required\n"
        "-F\t\tDon't fork into background\n"
        "-e\t\tPass on server process environment to child process\n"
        "(Syslog support not compiled in, using stderr)\n"
        "-m\t\tDon't display the motd on login\n"
        "-w\t\tDisallow root logins\n"
        "-G\t\tRestrict logins to members of specified group\n"
        "-s\t\tDisable password logins\n"
        "-g\t\tDisable password logins for root\n"
        "-B\t\tAllow blank password logins\n"
        "-t\t\tEnable two-factor authentication (both password and public key required)\n"
        "-T\t\tMaximum authentication tries (default 10)\n"
        "-j\t\tDisable local port forwarding\n"
        "-k\t\tDisable remote port forwarding\n"
        "-a\t\tAllow connections to forwarded ports from any host\n"
        "-c command\tForce executed command\n"
        "-p [address:]port\n"
        "\t\tListen on specified tcp port (and optionally address),\n"
        "\t\tup to 10 can be specified\n"
        "\t\t(default port is 22 if none specified)\n"
        "-P PidFile\tCreate pid file PidFile\n"
        "\t\t(default /var/run/dropbear.pid)\n"
        "-l <interface>\n"
        "\t\tinterface to bind on\n"
        "-i\t\tStart for inetd\n"
        "-W <receive_window_buffer> (default 24576, larger may be faster, max 10MB)\n"
        "-K <keepalive>  (0 is never, default 0, in seconds)\n"
        "-I <idle_timeout>  (0 is never, default 0, in seconds)\n"
        "-z    disable QoS\n"
